class Task:
    def __init__(self, ident, prio):
        self.ident = ident
        self.prio = prio
        self.count = 0
    def run(self, packet):
        self.count += 1
        return packet + self.prio
class Worker(Task):
    def run(self, packet):
        self.count += 1
        return (packet * 3 + self.ident) % 9973
class Handler(Task):
    def run(self, packet):
        self.count += 2
        return packet ^ self.ident
class Scheduler:
    def __init__(self, tasks):
        self.tasks = tasks
    def schedule(self, rounds):
        packet = 1
        for r in range(rounds):
            t = self.tasks[r % len(self.tasks)]
            packet = t.run(packet) % 100003
        return packet
