class V:
    def __init__(self, x, y, z):
        self.x = x
        self.y = y
        self.z = z
    def __add__(self, o):
        return V(self.x + o.x, self.y + o.y, self.z + o.z)
    def __sub__(self, o):
        return V(self.x - o.x, self.y - o.y, self.z - o.z)
    def scale(self, k):
        return V(self.x * k, self.y * k, self.z * k)
    def dot(self, o):
        return self.x * o.x + self.y * o.y + self.z * o.z
def hit(center, radius, origin, d):
    oc = origin - center
    b = oc.dot(d)
    c = oc.dot(oc) - radius * radius
    disc = b * b - c
    if disc < 0:
        return -1.0
    return -b - disc ** 0.5
