        d = V((px - 40) / 40.0, (py - 30) / 40.0, -1.0)
        d = d.scale(1.0 / d.dot(d) ** 0.5)
        t = hit(center, 1.0, origin, d)
        if t > 0:
            hits += 1
            p = origin + d.scale(t)
            n = (p - center).scale(1.0)
            shade += max(0.0, n.dot(V(0.577, 0.577, 0.577)))
