        return N(k)
    cur = root
    while True:
        if k < cur.k:
            if cur.l is None:
                cur.l = N(k)
                return root
            cur = cur.l
        else:
            if cur.r is None:
                cur.r = N(k)
                return root
            cur = cur.r
