def parse(s):
    pos = [0]
    def peek():
        return s[pos[0]] if pos[0] < len(s) else ""
    def number():
        start = pos[0]
        while peek().isdigit():
            pos[0] += 1
        return int(s[start:pos[0]])
    def factor():
        if peek() == "(":
            pos[0] += 1
            v = expr()
            pos[0] += 1
            return v
        return number()
    def term():
        v = factor()
        while peek() in ("*", "/"):
            op = peek()
            pos[0] += 1
            r = factor()
            v = v * r if op == "*" else v // r
        return v
    def expr():
        v = term()
        while peek() in ("+", "-"):
            op = peek()
            pos[0] += 1
            r = term()
            v = v + r if op == "+" else v - r
        return v
    return expr()
